Sys.setlocale('LC_ALL','Chinese (Simplified)_China.utf8')
suppressPackageStartupMessages({library(data.table);library(edgeR);library(quadprog)})
a<-commandArgs(TRUE); B<-if(length(a))as.integer(a[1]) else 100L
root<-Sys.getenv('OA_REPO_ROOT',unset=getwd()); inp<-file.path(root,'data/components/bulk/inputs'); f5<-file.path(root,'data/components/mixtures/inputs'); baseout<-file.path(root,'results/simulation_legacy'); chunk<-if(length(a)>=2)as.integer(a[2]) else 0L;out<-if(chunk>0)file.path(baseout,paste0('批次_',chunk)) else baseout;dir.create(out,showWarnings=FALSE,recursive=TRUE);set.seed(20261120+chunk)
p<-readRDS(file.path(f5,'donor_count_profiles.rds')); md<-as.data.table(p$lineage_metadata); md[,cl:=fcase(celltype%in%c('B_cell','Plasma','Mast'),'B_Plasma_Mast',celltype%in%c('T_cell','NK'),'T_NK',default=celltype)];cls<-c('B_Plasma_Mast','Endothelial','Fibroblast','Macrophage','Pericyte','T_NK')
buildref<-function(ids){m<-sapply(cls,function(cc)if(cc=='Macrophage')rowSums(p$clean_mac_sum[,p$donor_metadata$sample[p$donor_metadata$group %in% ids],drop=FALSE]) else rowSums(p$lineage_sum[,md[group%in%ids & cl==cc,profile_id],drop=FALSE]));rownames(m)<-rownames(p$lineage_sum); colnames(m)<-cls;sweep(m,2,colSums(m),'/')*1e6}
ref<-buildref(c('Healthy','OA')); rh<-buildref('Healthy');ro<-buildref('OA')
bulk<-fread(text=paste(readLines(gzfile(file.path(inp,'GSE89408_counts.txt.gz')),warn=FALSE),collapse='\n')); gn<-bulk[[1]];counts<-as.matrix(bulk[,-1]);storage.mode(counts)<-'double';rownames(counts)<-gn;bulkcp<-sweep(counts,2,colSums(counts),'/')*1e6
shared<-intersect(rownames(ref),rownames(bulkcp));ref<-ref[shared,];rh<-rh[shared,];ro<-ro[shared,];bulkcp<-bulkcp[shared,];specific<-ref/rowMeans(ref);specific[!is.finite(specific)]<-0
mk<-unique(unlist(lapply(seq_along(cls),function(k){v<-specific[,k];v[ref[,k]<=10]<--Inf;names(sort(v,decreasing=TRUE))[seq_len(min(120,sum(is.finite(v))))]})));mk<-mk[!is.na(mk)]
fac<-ifelse(rowMeans(ref[mk,])>1,rowMeans(bulkcp[mk,])/rowMeans(ref[mk,]),1); adj<-rep(1,nrow(ref));names(adj)<-rownames(ref);adj[mk]<-fac
# Apply across all shared genes to build a plausible synthetic bulk scale; archived calibration itself uses marker genes only.
f_all<-ifelse(rowMeans(ref)>1,rowMeans(bulkcp)/rowMeans(ref),1);f_all<-pmin(pmax(f_all,.05),20); G<-ref*f_all;G<-sweep(G,2,colSums(G),'/')
# Marker reference reproduces published algorithm, including its actual unclipped factors.
S0<-ref[mk,]*fac; Sarch<-sweep(S0,2,colSums(S0),'/'); S<-sweep(G[mk,],2,colSums(G[mk,]),'/')
ratio<-pmin(4,pmax(.25,(ro[,'Macrophage']+1)/(rh[,'Macrophage']+1)))^.5
GO<-G;GO[,'Macrophage']<-GO[,'Macrophage']*ratio;GO[,'Macrophage']<-GO[,'Macrophage']/sum(GO[,'Macrophage'])
meta<-as.data.table(fread(file.path(inp,'deconv_proportions_218.csv')));meta<-meta[disease%in%c('Normal','Osteoarthritis') & is.finite(fit_r)&fit_r>=.6];setcolorder(meta,unique(c('sample','disease',cls)));stopifnot(nrow(meta)==44,sum(meta$disease=='Osteoarthritis')==19)
prop<-as.matrix(meta[,..cls]);prop<-prop/rowSums(prop);label<-as.integer(meta$disease=='Osteoarthritis');L<-colSums(counts)[match(meta$sample,colnames(counts))];stopifnot(!anyNA(L))
lines<-strsplit(readLines(file.path(inp,'macrophage_39_c5.go.v2022.1.Hs.symbols.gmt')), '\t');sets<-setNames(lapply(lines,function(x)unique(x[-c(1,2)])),vapply(lines,`[`,character(1),1))
# Simulated reference discrepancy: deliberately imposed cell-type-specific independent log-normal perturbations.
fitfun<-function(S,y){mu<-rowMeans(S);sdv<-apply(S,1,sd);sdv[sdv<1e-8]<-1;A<-(S-mu)/sdv;z<-(y-mu)/sdv;D<-crossprod(A)+diag(1e-8,ncol(A));q<-as.numeric(crossprod(A,z)); as.numeric(solve.QP(D,q,cbind(rep(1,ncol(S)),diag(ncol(S))),c(1,rep(0,ncol(S))),meq=1)$solution)}
fit_scores<-function(C,pro,lab,truth){d<-DGEList(C);keep<-filterByExpr(d,group=factor(lab));d<-d[keep,,keep.lib.sizes=FALSE];d<-normLibSizes(d,method='TMM');E<-cpm(d,log=TRUE,prior.count=1);use<-lapply(sets,intersect,y=rownames(E));Z<-t(scale(t(E)));Z[!is.finite(Z)]<-0; z<-sapply(use,function(g)if(length(g)>=3)colMeans(Z[g,,drop=FALSE])else rep(NA_real_,ncol(E)));ans<-lapply(seq_along(sets),function(k){y<-z[,k];if(anyNA(y)||sd(y)<1e-10)return(NULL);y<-as.numeric(scale(y));u<-summary(lm(y~lab))$coef['lab',];v<-summary(lm(y~lab+pro))$coef['lab',];o<-summary(lm(y~lab+truth))$coef['lab',];data.table(geneset=names(sets)[k],beta_unadjusted=u[1],p_unadjusted=u[4],beta_estimated=v[1],p_estimated=v[4],beta_oracle=o[1],p_oracle=o[4])});rbindlist(ans)}
scenarios<-c('null','composition_only','expression_only','both'); runs<-expand.grid(scenario=scenarios,reference=c('matched','mismatch','recalibrated'),replicate=seq_len(B),stringsAsFactors=FALSE);allout<-vector('list',nrow(runs));qc<-vector('list',nrow(runs));cat('START',nrow(runs),'runs\n');flush.console()
for(i in seq_len(nrow(runs))){s<-runs$scenario[i];rr<-runs$reference[i];w<-prop;if(s%in%c('null','expression_only'))w<-w[sample(seq_len(44)),,drop=FALSE];has_expr<-s%in%c('expression_only','both');Y<-G%*%t(w);if(has_expr){change<-GO[,'Macrophage']-G[,'Macrophage'];Y<-Y+tcrossprod(change,w[,'Macrophage']*label)};mu<-sweep(Y,2,L,'*');C<-matrix(rnbinom(length(mu),mu=as.vector(mu),size=50),nrow=nrow(mu),dimnames=list(rownames(G),meta$sample));C[!is.finite(C)]<-0
  if(rr=='matched'){Sfit<-S}else if(rr=='mismatch'){Sfit<-S*exp(matrix(rnorm(length(S),0,.3),nrow(S)));Sfit<-sweep(Sfit,2,colSums(Sfit),'/')}else{rem<-setdiff(colnames(bulkcp),meta$sample);simcp<-sweep(C[mk,,drop=FALSE],2,colSums(C),'/')*1e6;mb<-(rowSums(bulkcp[mk,rem,drop=FALSE])+rowSums(simcp))/(length(rem)+ncol(C));fc<-ifelse(rowMeans(ref[mk,])>1,mb/rowMeans(ref[mk,]),1);Sfit<-ref[mk,]*fc;Sfit<-sweep(Sfit,2,colSums(Sfit),'/')}
  mac_mass<-sum(G[mk,'Macrophage'])+as.integer(has_expr)*label*(sum(GO[mk,'Macrophage'])-sum(G[mk,'Macrophage'])); true_marker<-w[,'Macrophage']*mac_mass/(as.numeric(w%*%colSums(G[mk,,drop=FALSE]))+w[,'Macrophage']*(mac_mass-sum(G[mk,'Macrophage'])));obs<-sweep(C[mk,,drop=FALSE],2,colSums(C[mk,,drop=FALSE]),'/');pred<-vapply(seq_len(ncol(C)),function(j)fitfun(Sfit,obs[,j]),numeric(6));pest<-as.numeric(pred[match('Macrophage',cls),]);fit<-fit_scores(C,pest,label,true_marker);fit[,':='(scenario=s,reference=rr,replicate=runs$replicate[i])];allout[[i]]<-fit; qc[[i]]<-data.table(scenario=s,reference=rr,replicate=runs$replicate[i],cor=cor(pest,true_marker),rmse=sqrt(mean((pest-true_marker)^2)),bias=mean(pest-true_marker));if(i%%100==0){saveRDS(list(completed=i,results=allout[seq_len(i)],quality=qc[seq_len(i)]),file.path(out,'运行中_检查点.rds'))};if(i%%10==0){cat('DONE',i,'of',nrow(runs),'\n');flush.console()}}
res<-rbindlist(allout);res[,':='(q_unadjusted=p.adjust(p_unadjusted,'BH'),q_estimated=p.adjust(p_estimated,'BH'),q_oracle=p.adjust(p_oracle,'BH')),by=.(scenario,reference,replicate)];res[,delta:=beta_unadjusted-beta_estimated];fwrite(res,file.path(out,sprintf('scenario_results_B%d.csv.gz',B)));q<-rbindlist(qc);fwrite(q,file.path(out,sprintf('reference_accuracy_B%d.csv',B)));med<-res[,.(median_delta=median(delta)),by=.(scenario,reference,replicate)];fwrite(med,file.path(out,sprintf('replicate_median_delta_B%d.csv',B)));z<-res[,.(median_delta_all_effects=median(delta),mean_n_sig_unadjusted=sum(q_unadjusted<.05)/uniqueN(replicate),mean_n_sig_estimated=sum(q_estimated<.05)/uniqueN(replicate),mean_n_sig_oracle=sum(q_oracle<.05)/uniqueN(replicate),mean_beta_unadjusted=mean(beta_unadjusted),mean_beta_estimated=mean(beta_estimated),mean_beta_oracle=mean(beta_oracle),n_runs=uniqueN(replicate)),by=.(scenario,reference)];z<-merge(z,med[,.(median_of_medians=median(median_delta),q025_run_medians=quantile(median_delta,.025),q975_run_medians=quantile(median_delta,.975),proportion_median_ge_observed=mean(median_delta>=0.551326224444614)),by=.(scenario,reference)],by=c('scenario','reference'));fwrite(z,file.path(out,sprintf('scenario_summary_B%d.csv',B)));writeLines(capture.output(sessionInfo()),file.path(out,'R_sessionInfo.txt'));cat('FINISHED\n')








